  str_pet_equip_name_1602301 = "Bíblia Sangrenta: Calamidade",
  str_pet_equip_name_1602311 = "Espada de Sangue, \"Maré Carmesim\"",
  str_pet_equip_name_1502321 = "Espada do Sangue Sagrado",
  str_pet_equip_name_1602331 = "Devaneio Espumante",
  str_pet_equip_name_1602341 = "Astrumnox",
  str_pet_equip_name_1502351 = "Edel Schwert",
  str_pet_equip_name_1602371 = "Ária Sonhadora",
  str_pet_equip_name_1602381 = "Insígnia do Juramento Eterno",
  str_pet_equip_intro_1200501 = "Esses dois tacos têm um tamanho semelhante ao de tacos normais, mas suas serras circulares aumentam muito sua letalidade na hora de cortar ou golpear.",
  str_pet_equip_intro_1300221 = "Chainsaw Rick é conhecido por ligar sua serra elétrica e avançar sobre o inimigo, golpeando cegamente o que quer que esteja à sua frente. Seu poder cresce na medida em que sua serra esquenta. Por isso, ele precisa reabastecê-la continuamente com diesel, tomando alguns goles no processo. Quando a serra sobreaquece, seu poder dispara consideravelmente.",
  str_pet_equip_intro_1300461 = "Um conjunto de quatro itens usados pelos quatro membros do esquadrão de Keating. Inicialmente, eles pareciam comuns, mas logo descobriu-se que esses itens tinham uma conexão com o Pergaminho de Cântico, não só aumentando o poder de Lumináticas de som, mas também produzindo efeitos mais poderosos quando coordenados corretamente.",
  str_pet_equip_intro_1300471 = "Quando Zoya viajou para o Mar Profundo, o Quarkium de lá teve um misterioso efeito nela, colocando-a em um sono profundo. Depois de deixar o Mar Profundo, Zoya obteve parte de um cristal de Quarkium e aprendeu a utilizar seu poder. Ela o embutiu em seu cajado de gelo, aumentando sua força em combate.",
  str_pet_equip_intro_1300491 = "Um par de espadas negras que Istvan comprou para Seleucid quando ele se juntou à sua gangue. Dizem que estas duas espadas leves são relíquias antigas, eternamente cobertas de gelo. Depois de recebê-las, Seleucid dominou a arte de empunhar duas espadas.",
  str_pet_equip_intro_1300511 = "Um lança-granadas de alta temperatura e um pequenino rifle de precisão: essa combinação de armas é usada exclusivamente por Sork e Bekk. Sork empunha o lança-granadas, Bekk o rifle e os dois trabalham em perfeita harmonia para derrotar facilmente hordas de inimigos.",
  str_pet_equip_intro_1300521 = "Uma pena deixada para Dove por seus pais. Ela pode aumentar sua velocidade e melhorar o poder de suas Lumináticas, permitindo-a arremessar lâminas com mais precisão e agilidade.",
  str_pet_equip_intro_1300531 = "A espada de Jomu, guardada em um container. Leve e fácil de empunhar e carregar. Depois de anos de experiência, Jomu sabe exatamente como usá-la para potencializar sua força e causar destruição no campo de batalha.",
  str_pet_equip_intro_1300581 = "Depois de tornar-se uma cavaleira, Amy logo virou uma porta-estandarte e recebeu esta lança. Ela pode injetar suas próprias Lumináticas na Lança Aurora, transformando-a em um estandarte capaz de inspirar seus colegas e aumentar o moral da equipe.",
  str_pet_equip_intro_1300591 = "Quando Pepi usou sua própria chama pela primeira vez, ela acidentalmente se queimou. De todas as penas que perdeu naquele dia, apenas esta sobreviveu, retendo uma centelha da chama. Desde então, Pepi guardou a pena, usando seu poder para aumentar sua agilidade.",
  str_pet_equip_intro_1300741 = "Quando as habilidades de White Dwarf surgiram, duas esferas apareceram ao seu redor. Elas podem atacar inimigos a distância e se unir para causar uma enorme explosão capaz de eliminar todos os inimigos próximos.",
  str_pet_equip_intro_1300801 = "A obsessão de Unimet por máquinas a leva a criar constantemente braços robóticos, e dizem que ela já produziu 23 deles... Esses braços são guardados em sua enorme mochila, que está sempre abarrotada de armas. Ela consegue controlar esses braços para lutar e trabalhar sempre que precisa.",
  str_pet_equip_intro_1300821 = "Ophina nasceu portando uma turquesa. Enquanto crescia, a turquesa tornou-se mais e mais brilhante, aumentando o poder da Lúmina em seu interior e formando uma misteriosa conexão com os grandes chifres esmeralda em sua cabeça. Ophina embutiu essa turquesa em seu cajado, e agora a usa para guiar as Lumináticas em seu interior.",
  str_pet_equip_intro_1300871 = "N/A",
  str_pet_equip_intro_1400071 = "Este dardo de forma peculiar é conhecido como a Foice. Quando Clover juntou-se à Rediesel Wrench, ele foi modificado para se adequar ao corpo pequeno da garota. Clover dedicou muitas horas para dominar o uso da Foice, e agora que está proficiente é capaz de arremessá-la mais rápido e mais longe.",
  str_pet_equip_intro_1400081 = "Depois de se juntar à Rediesel Wrench, Tiny One não podia lutar devido à sua idade e outras razões – até que encontrou este farol. Ela o estudou cuidadosamente e o modificou para emitir um poderoso raio de luz que pode ser usado contra Eclipsitas.",
  str_pet_equip_intro_1400161 = "Kafka encontrou esta arma enquanto caçava Eclipsitas nas ruínas misteriosas do Deserto Rediesel. O rifle, que parece ter sua origem em uma antiga civilização, possui uma modificação eletromagnética que aumenta sua precisão e lança poderosas balas perfurantes.",
  str_pet_equip_intro_1400171 = "Odi modificou esta furadeira elétrica para dar a ela um acabamento negro lustroso e um brilho vermelho. Ainda que um pouco robusta, ela é muito leve, e Rabbie pode manuseá-la facilmente. Agora que dominou seu uso, ela tornou esta furadeira elétrica sua arma exclusiva.",
  str_pet_equip_intro_1400321 = "Angel nasceu com um par de lindas asas, mas uma delas foi ferida permanentemente em um ataque Eclipsita, restando apenas algumas penas. Angel carrega essas penas consigo, esperando um dia restaurar sua asa perdida.",
  str_pet_equip_intro_1400351 = "Esta foi a primeira pena que nasceu em Eho, ocultada em seguida por outras penas quando ela cresceu. No entanto, depois que Eho passou por muitas aventuras, a pena sofreu uma fascinante transformação que resultou em uma marca peculiar. Ela tornou-se a arma única de Eho.",
  str_pet_equip_intro_1400401 = "Joanie Boom sempre foi fascinada por explosões. Depois de se juntar à Rediesel Wrench, essa paixão cresceu. Sempre que luta, ela usa todo o tipo de bombas cuidadosamente elaboradas para explodir os Eclipsitas com chamas ferozes. Na sua opinião, não há nada no mundo mais extraordinário que uma boa bomba.",
  str_pet_equip_intro_1400411 = "A Srta. Blanc sempre carrega uma mala branca consigo. Alguns dizem que ela contém armas misteriosas; outros, que contém diversos relatos oculares que a Srta. Blanc registrou. No entanto, ninguém nunca viu a mala aberta...",
  str_pet_equip_intro_1400441 = "Usando tecnologia de Illumina e metais raros, pesquisadores da Cidade Gannon elaboraram sua última arma, especialmente para Vivian: uma lâmina afiada, leve e fina. Ela também pode orientar a Lúmina no corpo de Vivian, aumentando seu poder.",
  str_pet_equip_intro_1400451 = "O sangue especial que corre pelo corpo de Nails lhe concede grande força, mas também traz uma dor constante. Para suprimir o poder de seu sangue, Nails se feriu com um martelo sagrado. No entanto, esse martelo ensanguentado também ganhou um poder misterioso, permitindo que Nails use sua força para destruir inimigos.",
  str_pet_equip_intro_1400481 = "Um par de adagas onduladas extremamente afiadas. Dayna as usa desde que começou a viajar com Robyn. Depois de anos de combate, ela se tornou proficiente. As adagas não apenas cortam facilmente, mas também liberam a Lúmina no corpo de Dayna para eliminar rapidamente seus inimigos.",
  str_pet_equip_intro_1400541 = "Esta lanterna com uma longa corrente é o símbolo da Vigília e nunca se apaga. Mesmo nos lugares mais escuros, Nadine, a Capitã da Vigília, pode erguer a lanterna e usar suas próprias Lumináticas para emitir uma luz intensa, dispersando as trevas e afastando os inimigos.",
  str_pet_equip_intro_1400571 = "Ainda que pareça apenas um cajado, ele foi feito com Tecnologia de Illumina de ponta. Pode se transformar em uma adaga e ser usado para cura, apaziguando as emoções instáveis no coração de Philyshy.",
  str_pet_equip_intro_1400611 = "Depois de descobrir a verdadeira força de Chandra, Gronru fez um anel para ela. Esse anel permite que Chandra transforme as emoções negativas que absorve para lançá-las em uma magnífica rajada de fogo, tornando-se um dos produtos mais avançados da Tecnologia de Illumina.",
  str_pet_equip_intro_1400681 = "Enquanto estava fazendo uma entrega, Wendy encontrou um raro furação no deserto. Quando achou que havia encontrado seu fim, uma pena pousou em seu rosto. De repente, Wendy sentiu uma coragem inexplicável e escapou do furacão. Desde aquele dia, ela mantém a pena sempre consigo como uma lembrança de sua força e uma fonte de coragem.",
  str_pet_equip_intro_1400731 = "Este tridente pertence à dupla, mas normalmente Patsy é quem o empunha, já que possui um dom natural para controlá-lo. Quando empunhado por Patty, ela o usa apenas para golpear os inimigos. Ainda que seja capaz de eliminar seus oponentes rapidamente, ele também pode ferir os aliados e deve ser usado com cautela.",
  str_pet_equip_intro_1400791 = "Uma herança da família de Michenny que pode ser rastreada até a fundação de Lumópolis. Um item fortalecido pela fé de seu usuário, a Balança do Juízo tem a habilidade de julgar seus inimigos, transformando palavras em ataques mentais.",
  str_pet_equip_intro_1400811 = "A Equipe Técnica da Rediesel Wrench modificou especialmente o equipamento de box de Brock, reforçando sua dureza. Esse equipamento também usa as turbinas de Brock para aumentar o impacto de sua sucção e injeção a jato, permitindo que ele nocauteie inimigos facilmente.",
  str_pet_equip_intro_1400831 = "Uma vassoura branca com um estilo mecânico único, especialmente desenvolvida no laboratório de pesquisas científicas da Federação Illumina. Possui um complexo dispositivo de transmissão mecânica que trabalha em conjunto com as Lumináticas especiais de Lilliam, permitindo que ela limpe qualquer lixo e todo o tipo de inimigos em combate.",
  str_pet_equip_intro_1400851 = "A mala de Jane é repleta de todo o tipo de arquivos e materiais, como os segredos de Umbraton, os conflitos entre as notórias gangues, acordos secretos entre o alto escalão da nação e muito mais. Segundo a própria Jane, essa é a verdadeira fonte de sua força.",
  str_pet_equip_intro_1400861 = "Esta espada cerimonial foi supostamente feita de acordo com projetos desenhados pela própria Uriah, e conhecida como Flor de Oração. Apesar de possuir resiliência alta, sua lâmina é fina demais e não pode competir com a maioria das outras armas. A verdade é que apenas Uriah pode exercer todo o seu poder ao usar sua técnica secreta.",
  str_pet_equip_intro_1400911 = "Esta é a harpa do pai de Chloe. Tocando habilmente, ela pode colocar sua própria Luminática nas notas, usando a Luminática tanto para influenciar os outros quanto para acalmar as almas feridas de seus companheiros.",
  str_pet_equip_intro_1500091 = "Uma caixa concedida por Victoria após entrar para a True Order. Contém algum tipo de ser que pode devorar qualquer coisa. Seu objetivo não é claro, e tudo que se sabe é que gosta de memórias dolorosas. Entretanto, após Faust obter esta caixa, seus pesadelos não o perturbam mais.",
  str_pet_equip_intro_1500121 = "Uma arma feita, especialmente, para a Nemesis, pelo departamento de pesquisa da Federação Illumina, ela inclui capacidade de manipulação de corrente elétrica superior. Ao controlá-la para atordoar ou ferir inimigos, ela requer a versatilidade de Nemesis em várias situações.",
  str_pet_equip_intro_1500131 = "Este foi o primeiro cristal de gelo que Noah fez usando sua própria Luminática. Tem um formato muito especial, e mesmo depois que aprendeu a fazer mais cristais de gelo, ela decidiu manter esta lembrança única. Durante certa aventura, ela descobriu que este cristal de gelo havia mudado, empunhando o poder da “Esperança” para aumentar a efetividade de combate de Noah.",
  str_pet_equip_intro_1500181 = "Enterrada no deserto, esta guitarra foi descoberta pelos membros de Rediesel Wrench. No início, ela só foi deixada no canto do caminhão, mas após Regina se juntar a Rediesel Wrench, descobriu que esta guitarra estava perfeitamente afinada com seu próprio estilo de música, e a guitarra fez com que ela liberasse sua força interna.",
  str_pet_equip_intro_1500201 = "Esta lança foi dada à Carleen pelo seu pai, o Duque Sorla, no dia em que ela recebeu o título de cavaleiro. Depois de incontáveis batalhas em suas mãos, a marca especial de Carleen apareceu nela. A lança de Carleen ficará extremamente poderosa quando infundida com materiais sublimes.",
  str_pet_equip_intro_1500211 = "Uma tesoura feita especialmente pela Federação Illumina para Jola. Com o tamanho ajustável, primeiro Jola a usou como ferramenta de jardinagem para ajudar a cultivar as plantas, mas logo ela desenvolveu novas características para que tivesse papel fundamental na batalha.",
  str_pet_equip_intro_1500311 = "Esta lança foi dada à Carleen pelo seu pai, o Duque Sorla, no dia em que ela recebeu o título de cavaleiro. Depois de incontáveis batalhas em suas mãos, a marca especial de Carleen apareceu nela. A lança de Carleen ficará extremamente poderosa quando infundida com materiais sublimes.",
  str_pet_equip_intro_1500331 = "Um arco longo feito especialmente para Vice pelo laboratório de pesquisa científico da Cidade Gannon. Parecido com uma armadura de dragão, ele é reforçado com materiais especiais que aumentam a precisão da Luminática de Vice e seus poderes.",
  str_pet_equip_intro_1500341 = "Esta lança foi dada à Carleen pelo seu pai, o Duque Sorla, no dia em que ela recebeu o título de cavaleiro. Depois de incontáveis batalhas em suas mãos, a marca especial de Carleen apareceu nela. A lança de Carleen ficará extremamente poderosa quando infundida com materiais sublimes.",
  str_pet_equip_intro_1500361 = "Hydrad encontrou este objeto em ruínas antigas e logo descobriu que ele possui um poder ancião misterioso. Parece uma garrafa de vidro emitindo uma bela luz azul, e pode libertar magia especial para invocar criaturas mágicas conhecidas como “Lobos Sombrios”, para ajudar Hydrad em batalhas.",
  str_pet_equip_intro_1500421 = "Como arma primária, a Faca de Barton é uma versão modificada da épée feita com materiais raros e tem a habilidade de guiar Lúmina para causar dano fatal. A submetralhadora “Modificada Sherman” melhorada, é uma versão modificada da submetralhadora Sherman básica, incluindo capacidade de munição em dobro, cano mais pesado e poder de fogo sustentado muito melhorado.",
  str_pet_equip_intro_1500701 = "Um anel dourado gravado com palavras misteriosas. Pode guiar o poder dentro do sangue de Leona e utilizar o poder puro da chama, conhecido como “Sopro do Dragão”, para destruir tudo à vista.",
  str_pet_equip_intro_1500751 = "Usando o conhecimento adquirido pela Federação Illumina e sua inspiração genial, Odi escolheu uma seleção de materiais úteis da reserva de espólios da Rediesel Wrench, e gradualmente aperfeiçoou um tipo de grande cabo óptico—uma arma estranha que funciona com energia autopropulsora e que se move como um verme de areia.",
  str_pet_equip_intro_1500761 = "Parece que pertencia a um tipo de monstro das profundezas do mar, apesar de Kleken dizer que criou este tentáculo usando sua própria Luminática especial. A fonte verdadeira é desconhecida.",
  str_pet_equip_intro_1500781 = "Apesar de ser um cano de ferro comum, ainda pode ser mortal nas mãos certas. Robyn pode usar sua própria Luminática para formar uma lâmina de vento afiada neste cano, que facilmente corta a armadura do inimigo com um poder aterrorizante.",
  str_pet_equip_intro_1500841 = "Um cajado dourado puro das Gêmeas Víbora, com um design especial que permite que chamas circulem dentro dele. Istvan pode usá-lo para invocar uma chama fantasma azul que incendeia tudo ao redor. A energia lançada por estas chamas pode derrotar os inimigos e fortalecer a habilidade de combate de toda a equipe.",
  str_pet_equip_intro_1500881 = "Este saco de bomba de couro sempre está cheio de bombas produzidas em massa. Geralmente, estas bombas não são muito poderosas, mas se Maggie injetar uma grande quantidade de Lúmina, eles podem alcançar um poder explosivo cataclísmico.",
  str_pet_equip_intro_1500901 = "Uma serra elétrica circular modificada com uma alça do tipo cordão única. Dizem que originalmente era um microfone, supostamente foi convertida em arma após a demanda de Barbara para lidar com seus fãs loucos... Entretanto, Barbara nega isso veementemente.",
  str_pet_equip_intro_1500921 = "Pact não carrega este objeto parecido com roda e coberto com espinhos murchos por escolha própria. É como se fosse um fantasma sem descanso—não importa onde seja jogado, ou quão longe ela corra, ele sempre volta. Entre mistérios e horrores, ele concede a ela grande poderes.",
  str_pet_equip_intro_1600011 = "Este grande espelho é uma relíquia de Northland que pode produzir ilusões misteriosas. Conhecido como “Espelho de Northland”, ele é indispensável para Nikinis. Ela pode usar Luminática para fazer o espelho flutuar, mas também pode canalizar Lúmina através do espelho e suas flores para destruir oponentes em batalha.",
  str_pet_equip_intro_1600021 = "Assim como Hiiro, esta lâmina é do Oriente. Dizem que o mestre de Hiiro, Sakae Shigeo, concedeu a esta lâmina grandes poderes e sua força vital, sintonizando-a com a própria essência de Hiiro. Por isso, esta arma é chamada de \"Katana: Sakae\". É muito poderosa, mas o uso prolongado consumirá o poder do corpo de Hiiro.",
  str_pet_equip_intro_1600031 = "Esta lança foi dada à Carleen pelo seu pai, o Duque Sorla, no dia em que ela recebeu o título de cavaleiro. Depois de incontáveis batalhas em suas mãos, a marca especial de Carleen apareceu nela. A lança de Carleen ficará extremamente poderosa quando infundida com materiais sublimes.",
  str_pet_equip_intro_1600041 = "Embora o morcego barbado branco de Kuma e os foguetes laranja de Pengy sejam assustadores, Kuma e Pengy não os usam como método de ataque principal. Em vez disso, usam Luminática poderosa e cooperação sólida para derrotar os inimigos em combate.",
  str_pet_equip_intro_1600051 = "Depois de Mia se mudar para perto de Umbraton, a personalidade de seu “Baba Yaga” causou confusões pela cidade, até o ponto de rumores sobre a “Aranha Negra” maliciosa começarem a circular. Depois de ouvir isso, Baba Yaga fez este ornamento especialmente com sua própria Luminática para aumentar o seu poder e o de Mia.",
  str_pet_equip_intro_1600061 = "Esta lança foi dada à Carleen pelo seu pai, o próprio Senhor da Cidade Schwartz, no dia em que ela recebeu o título de cavaleiro. Depois de incontáveis batalhas em suas mãos, a marca especial de Carleen apareceu nela, o que significa que ela obteve maestria completa com a arma, além de aumentar muito o poder do uso da lança.",
  str_pet_equip_intro_1600101 = "A “Magia de Bolso” de Louise pode criar todo o tipo de coisas, mas eventualmente elas desaparecem. A única coisa que restou foi este livro de contos de fadas. Acreditando que ele contém poderes mágicos, ela o levou, e ele realmente começou a aumentar seu poder interior.",
  str_pet_equip_intro_1600111 = "Esta katana é uma relíquia da família de Sharona, os Kartimas. Dizem que foi trazida do Oriente há milhares de anos. Sua lâmina constantemente projeta uma aura azul, similar a uma chama, e ela trabalha em sincronia perfeita com o Poder de Dragão de Sharona para gerar uma assustadora força destrutiva.",
  str_pet_equip_intro_1600141 = "Uma relíquia da família Schwartz, esta enorme espada conhecida como Lâmina do Soberano parece mais um símbolo de poder do que uma arma. Quando Schwartz a usa, invoca um leque de lâminas de luz que ficam ao redor de Schwartz como estrelas brilhantes e seguem suas ordens.",
  str_pet_equip_intro_1600191 = "O Tomo Negro de Victoria. Dizem que originalmente era um livro de magias, suas páginas são brancas na maior parte do tempo, e é impossível escrever nelas. A lenda diz que quando a Illumina vier, uma tinta vermelha preencherá as páginas do livro, deixando para trás uma profecia assim que desaparecer.",
  str_pet_equip_intro_1600231 = "Esta clarineta foi deixada para Connolly pelos seus pais. Ela passou sua infância solitária treinando clarineta, eventualmente despertando o poder escondido dentro dela. Da clarineta emergiram monstros com tentáculos, conhecidos como Antons. Antons seguem todos os comandos de Connolly, atacando ou prendendo seus inimigos.",
  str_pet_equip_intro_1600251 = "Apesar da pistola que apareceu com o trem de Charon, Other End, ser aparentemente uma arma de pederneira comum, após Charon libertar sua habilidade essa pistola formou uma conexão misteriosa com ele e seu poder melhorou tremendamente.",
  str_pet_equip_intro_1600261 = "O anel de fogo dourado que rodeia Uriel, está cheio de espaços que podem espirrar, armazenar e absorver chamas. Especialmente feito para Uriel, este item apenas suporta o poder de chama único dela.",
  str_pet_equip_intro_1600271 = "Uma espada em forma de anel com uma lâmina fina, especialmente feita para Michele em Lumópolis. Possui uma runa gravada pela própria Michele e pode guiar o poder do trovão pelo seu corpo para lançar impulsos ultrarrápidos.",
  str_pet_equip_intro_1600281 = "Uma grande caixa mecânica com uma estrutura em forma de cruz que contém vários Cascos de Água Benta. Raphaela pode controlar a água benta para causar dano a inimigos e curar aliados.",
  str_pet_equip_intro_1600291 = "Um bola de cristal amarelo-claro com um padrão simples. A bola de cristal aumenta a Luminática de Gabriela e permite que ela invoque e use a Gaiola a qualquer momento e em qualquer lugar.",
  str_pet_equip_intro_1600381 = "Esta máquina antiga conhecida como “Trono” é na verdade o veículo pessoal de Gronru—uma estrutura parecida com fortaleza que possui um imenso poder destrutivo. É controlada por Luvas Mecha do Trono, e Gronru pode fazer com que se movam em sincronia com suas ações.",
  str_pet_equip_intro_1600601 = "Estas três armas modificadas com formatos peculiares são muito distintas de revólveres. Com suas mãos mecânicas e carregador de 6 tiros, Jona pode disparar uma chuva de balas em seus inimigos, lançando fogo supressor poderoso.",
  str_pet_equip_intro_1600641 = "Wrath, uma comandante hábil, contratou o laboratório de pesquisa científica da Federação Illumina para personalizar especialmente esta matriz de máquinas flutuantes feita de ligas extremamente duras, que agora é chamada de \"Matriz da Patrulha\". Em seguida, ela aumentou seu controle sobre a Matriz da Patrulha usando suas luvas de boxe \"Ás\", permitindo que ela a comandasse com facilidade.",
  str_pet_equip_intro_1600771 = "Esta espada longa é conhecida como \"Lâmina Orbistelar\". Seu punho é rodeado por uma órbita em formato de cruz, simbolizando o poder da Queen do Norte. Embora tenha sido feita usando o poder puro da Aurora, Bethlehem não costuma utilizá-la em combate, e alguns até acreditam que seja mais um símbolo de sua identidade.",
  str_pet_equip_intro_1600891 = "Este é o nome coletivo para o “Cajado do Julgamento” e “Espada da Dádiva” empunhados por Irridon. O Cajado do Julgamento representa a linhagem de Irridon, enquanto a Espada da Dádiva representa o real desejo do seu coração.",
  str_pet_equip_intro_1500871 = "Depois de herdar sua devida posição, Beverly fez este broche parecido com uma lança, infundido com Lúmina, capaz de gerar grandes raios e que permite que Beverly crie lanças de raios mais rápidas e mortais.",
  str_pet_equip_intro_1500241 = "Chamote é a arma de fogo que Benny usa para fornecer fogo de cobertura e supostamente pode ser ajustada para propósitos diferentes. Celeritas é a baioneta muito afiada de Kuro. A combinação faz Benny e Kuro serem imbatíveis.",
  str_pet_equip_intro_1401011 = "Depois de Ansia entrar para o exército, ela deixou seu poder sônico ser conhecido, então os laboratórios técnicos em Gannon fizeram esse difusor especialmente para ela. Dizem que Ansia o usa para formar ondas sonoras em batalha.",
  str_pet_equip_intro_1600931 = "Este sabre não é apenas usado para comandar e treinar tropas, ele é imbuído com a Lúmina única de Migard. Por isso, emitiu um brilho misterioso que derrete todos os adversários que toca.",
  str_pet_equip_intro_1401021 = "Para controlar seus estouros esporádicos de plasma, Tessa comprou este par de luvas isoladas, especialmente feitas pela guilda em Umbraton; sua marca pessoal está embutida nelas. Com este par de luvas, Tessa pode controlar sua energia de plasma com mais facilidade.",
  str_pet_equip_intro_1500991 = "Esta é a espada mágica da família de Areia, com um feitiço poderoso. Tem um brilho preto ameaçador. Pode reunir Lúmina para um corte poderoso e deixa Areia controlar espinhos pretos para atacar inimigos e defender aliados.",
  str_pet_equip_intro_1600961 = "Uma roda de água especial criada por Sariel no auge do poder. Parece ser uma explosão de água, mas na verdade é extremamente sólida. Sariel acredita que seu formato e cor maravilhosos representam suas diferentes habilidades: \"Roda Bicolor\" e \"Roda Turva\". Ela aumenta ambas as habilidades.",
  str_pet_equip_intro_1500971 = "A experiência de cirurgião de Corax o tornou incomparável com bisturis. Para ele, qualquer lugar no inimigo é um ponto fraco e um alvo para dissecção. Estes bisturis são melhorados para serem ultracortantes com seu poder Lúmina, e podem ser manipulados para atacar a distância.",
  str_pet_equip_intro_1500981 = "Esta flor preta esteve com Cuscuta desde que nasceu. Mas quando seu poder se manifestou pela primeira vez, ela ficou branca. Cuscuta descobriu que ela está conectada com seu poder e começou a usá-la sempre.",
  str_pet_equip_intro_1400621 = "Quando Sylva começou a lutar esgrima, seu pai lhe deu uma vinha e o ensinou a transformá-la em rapieira com seus próprios poderes. Sylva guardou a vinha desde então para celebrar seu pai.",
  str_pet_equip_intro_1300941 = "O legado dos pais de Leah. Permite que Leah ataque com as forças da natureza e une o vapor da floresta para envolvê-la e seus colegas de equipe, aumentando sua defesa.",
  str_pet_equip_intro_1601031 = "Depois de descobrir o poder formidável e catastrófico de Eicy em sua pupila direita, a True Order criou este cajado para ela e o gravou com a sua marca pessoal, permitido que ela controle seu poder por meio do foco mágico.",
  str_pet_equip_intro_1501001 = "Esta é a chave para abrir a Cripta Estrelada. Com ela Sikare pode conjurar inúmeras armadilhas e monstros sob os inimigos, assim como a Cripta Estrelada real abaixo dela mesma, a fim de lhe conceder poder maior.",
  str_pet_equip_intro_1400951 = "Lester nasceu com mau cheiro corporal. Isso não acabou com sua autoestima, mas a estimulou a fazer uma fantasia especial e coletar seu cheiro em recipientes de gás que ela joga em inimigos para feri-los.",
  str_pet_equip_intro_1500561 = "Constantine pegou esta arma estragada durante sua jornada. Seu proprietário original lutou com Eclipsitas até a morte. Constantine admirou a determinação e fez dela a sua arma.",
  str_pet_equip_intro_1400671 = "Originalmente esculpido em um cristal normal, este colarinho tornou-se um rubi precioso com um calor maravilhoso quando Alice manifestou seus poderes pela primeira vez.",
  str_pet_equip_intro_1600301 = "Dizem que esta chave inglesa gigante foi usada pelo primeiro líder da Rediesel Wrench, e que somente aqueles que podem empunhá-la são qualificados para se tornarem líderes. A cabeça-de-martelo dura combinada com o poder de Sinsa possibilita que ela esmague qualquer coisa.",
  str_pet_equip_intro_1601051 = "Depois da recuperação de Eve, a equipe técnica da Rediesel Wrench fez estas luvas mecânicas especialmente para ela. Este par de luvas ajuda Eve a se recuperar mais rápido e aumenta sua habilidade para guiar a Lúmina por seu corpo.",
  str_pet_equip_intro_1501041 = "Depois de Dawn ficar cega, ela instalou o sino que sempre carregou consigo desde a infância em seu cajado. O doce som do sino acalma o coração de Dawn.",
  str_pet_equip_intro_1500711 = "Esta lâmina serrilhada pode parecer simples, mas é altamente compatível com Taki e pode guiar o poder das chamas em seu corpo.",
  str_pet_equip_intro_1701101 = "Uma lança enorme que tem estrutura mecânica complicada. Um banner azul e branco devastado pela guerra com um Brasão de Estrela voa no ar sobre ela. Esta lança é um dispositivo que aumenta a magia do trovão e pode ser usada como arma de curto alcance quando inimigos se aproximam.",
  str_pet_equip_intro_1701091 = "Este cajado enorme e pesado é hospedeiro de poderes mágicos especiais. Mythos é capaz de manipulá-lo com facilidade e conjurar feitiços poderosos.",
  str_pet_equip_intro_1701081 = "Depois de Frostfire ter controlado o cristal mágico chamado de Coração de Magma, ela imbuiu este longo chicote com poderes mágicos especiais, recebendo a habilidade de usá-lo para conjurar todos os tipos de feitiços de fogo em batalha.",
  str_pet_equip_intro_1701071 = "Uma enorme espada quebrada que parece um caixão sombrio. Ela tem um Brasão de Estrela e é pontuda e afiada. É feita de uma liga especial misteriosa e indestrutível. Ao mesmo tempo, tem um dispositivo embutido que amplifica a magia de água e nega ataques inimigos, além de redirecionar energia cinética para fornecer proteção a quem a está empunhando.",
  str_pet_equip_intro_1501131 = "Quando a True Order descobriu as habilidades de Bonacie, Victoria encomendou este bastão de fita de seda para que ela pudesse controlar seu poder de \"Intervenção Divina\" e convocar seu grupo de Avatares Sagrados para invocar meteoritos.",
  str_pet_equip_intro_1601111 = "Como uma flor, este cristal sanguíneo cresceu de seu corpo. Beryl achava que essa era a fonte de seu misterioso poder, então a mantinha junto de si o tempo todo para ter força.",
  str_pet_equip_intro_1501141 = "Um chicote curto originalmente usado para montar cavalos. Depois que a habilidade de Genevieve despertou, ela o combinou com seu poder flamejante para criar este Chicotão. Ele incinera os inimigos, enquanto o fecho de metal pode ser usado para capturá-los.",
  str_pet_equip_intro_1601121 = "Este broche feito do osso do crânio de manticora é a herança da família de Smokey e permite que o usuário controle uma manticora invocada, além de aprimorar seu domínio de Luminática.",
  str_pet_equip_intro_1601161 = "Uma pequena caixa contendo todos os tipos de ferramentas. Elas estão com Fleur há muitos anos, e ele as considera como uma extensão do seu próprio corpo.",
  str_pet_equip_intro_1401271 = "Este pedaço especial de papel vermelho contém um poder misterioso e está telepaticamente ligado a Pasolo. Segundo Pasolo, ele permite que ela veja seus falecidos pais e lhe dá uma grande força.",
  str_pet_equip_intro_1601171 = "Um conjunto de armas poderosas combinadas com uma grande espada, revólver e um lâmina de punho. A espada é usada para ataques pesados que podem derrubar o pior dos inimigos. O revolver e a lâmina de punho são integrados, o que promove mais flexibilidade na batalha garantindo ao usuário uma arma corpo a corpo secundária e um lançador poderoso de projéteis.",
  str_pet_equip_intro_1601191 = "Uma grande espada simples que foi reforçada com cabos de metal. Não só essa arma canaliza a Lúmina interior de Revy, mas os cabos de metal também permitem que ela lance a lâmina em inimigos distantes.",
  str_pet_equip_intro_1601221 = "Um nome dado ao relógio de bolso e pistola de Allura. O relógio de bolso amplifica os sentidos de Allura, aumenta sua mira e poder de fogo quando usa essa pistola antiga. Com esses dois em sua posse, ela então ganhou reconhecimento como pistoleira de Umbraton.",
  str_pet_equip_intro_1601211 = "Originalmente um emblema sagrado do Templo de Lumópolis, a gravura mudou depois que Paloma presenciou a morte de seus pais. Isso simboliza sua desilusão com sua fé e a decisão de seguir seu coração e o próprio caminho.",
  str_pet_equip_intro_1601151 = "Naroxel divide uma ressonância espiritual bizarra com os Vagalumes, permitindo que ela comande esses insetos pequenos e brilhantes para atacar seus inimigos. Essa bolsa de ouro feita de tecido transparente é onde ela mantém esses pequenos aliados.",
  str_pet_equip_intro_1300651 = "Depois de se tornar mensageira, Tweety cuidadosamente costurou um pena dela mesma no seu chapéu cilíndrico, que em breve tornou-se sua marca. Vesti-lo dá a Tweety uma eneorma vontade de viver.",
  str_pet_equip_intro_1601261 = "Bethel pode fazer essa arma alternar entre a forma de sino e a forma de bastão longo e usá-la para fazer um barulho que convoca seu espectro mágico, Frankel.",
  str_pet_equip_intro_1601291 = "Depois de se tornar um mercenário, o primeiro presente de Luke para si mesmo foi esta capa. Ele mesmo pintou o padrão para celebrar a memória de uma amiga borboleta, que guarda no fundo do coração. Esta capa pode fortalecer a conexão de Luke com os insetos e permite que ele use suas correntes com mais habilidade na batalha.",
  str_pet_equip_intro_1500551 = "Uma relíquia deixada para Pittman por seu pai. A gema azul embutida no topo tem o poder de invocar relâmpagos. Pittman pode liberar a habilidade de invocação de seu cajado para lançar relâmpagos devastadores sobre seus inimigos.",
  str_pet_equip_intro_1601201 = "Hedy raramente carrega essa arma com ela e a usa apenas em combate. Mesmo assim, sua familiaridade com a espada permite que ela se coordene perfeitamente com o Cavaleiro da Luz na batalha.",
  str_pet_equip_intro_1601231 = "Um cassetete distribuído exclusivamente para os Xerifes de Illumina. Depois de, finalmente, dominar o uso dessa arma, Cordy contratou uma equipe de cientistas para realizar um processo de aprimoramento especial, permitindo que ela atire chamas com um efeito de atordoamento eletrizante, o que a ajudou a neutralizar seus alvos com facilidade.",
  str_pet_equip_intro_1500151 = "Abreviação de \"bada bing bada boom”. É o nome do conjunto, dado por Hachi e Gin, à variedade de armas que carregam consigo. Incluindo um lançador de granadas, um fuzil de assalto especial e granadas de mão. Dizem que eles ganharam milhões em ativos usando essas armas para se estabelecer e, finalmente, construir uma vida para si próprios.",
  str_pet_equip_intro_1601311 = "Dizem que esse cajado longo foi feito da safira do primeiro espírito da montanha, que pode fortificar a força interna de quem o detém e desbloquear seu potencial escondido.",
  str_pet_equip_intro_1501321 = "Originalmente uma vinha comum da Floresta Barlavento. A vinha se transformou em um arco através da Lúmina fluindo do corpo de Lola após ela vagar pela floresta e dormir lá. Após Lola finalmente dominar sua Luminática, naturalmente tornou-se sua arma escolhida.",
  str_pet_equip_intro_1601331 = "Fantasia de empregada modificada das escamas de Tohru. Ela optou por ser a empregada de Kobayashi por amor. Para ela, isto não é um mero uniforme de trabalho.",
  str_pet_equip_intro_1601341 = "O último enfeite decorando a extremidade do rabo de cavalo da Kanna. É um artefato que pode controlar dragões ao soltar uma mágica interna.",
  str_pet_equip_intro_1501361 = "Boné personalizado usado pela Lucoa, com buracos feitos para os chifres protuberantes dela. Ela usa o tempo todo porque é difícil de tirar.",
  str_pet_equip_intro_1501351 = "Um tridente incorporando a força do mar. Nas mãos de Elma, pode liberar um poder de água incrível.",
  str_pet_equip_intro_1401371 = "Óculos antigos feitos de acordo com o estilo do portador. Tirado de uma foto de referência fornecida por Tohru.",
  str_pet_equip_intro_1601381 = "Siobhan encontrou esta tabuleta enquanto explorava as ruínas. Foi originalmente criado como uma ferramenta de gravação portátil a partir de um material especial. Mais tarde, ela descobriu que poderia usar Luminatics para aumentar a durabilidade do tablet e, com essa descoberta, tornou-se seu equipamento de defesa.",
  str_pet_equip_intro_1501391 = "Uma espada fina especialmente projetada para ser mais leve que o normal. Ele pode guiar melhor o Lumina no corpo de Erica, permitindo que ela emita relâmpagos poderosos na batalha.",
  str_pet_equip_intro_1601401 = "Esta espada tem uma lâmina curva que raramente é vista em Lumopolis ou mesmo no continente. Feito especialmente para Florine, é durável e excepcionalmente afiado, e permite que ela realize Luminatics mais poderosas.",
  str_pet_equip_intro_1601411 = "Suspeita-se que o taco de beisebol encontrado na pilha de peças de Rediesel Wrench seja feito de algum material especial. Não demorou muito para Ruby descobrir que era um ajuste perfeito para ela, e até fortalece seus Luminatics!",
  str_pet_equip_intro_1501421 = "Rouge fez esta arma ela mesma. Tem um carregador especial que pode ser preenchido com vários tipos de munição, e Rouge pode usar seu Lumina para detonar balas depois de disparadas. O alicate também é capaz de disparar fios de cobre para agarrar o inimigo.",
  str_pet_equip_intro_1601431 = "Há mais neste emblema no ventilador do que parece. Para Rinne, tem um significado profundo. Não apenas permite que ela veja a aura dos fantasmas, mas também fortalece seu controle sobre eles.",
  str_pet_equip_intro_1501441 = "Depois desse misterioso ritual, Kayano sempre podia ver o fantasma ligado a essa banda. Incapaz de afastá-lo, ela finalmente o aceitou e aproveitou os benefícios que ele trouxe, permitindo que aumentasse seu poder.",
  str_pet_equip_intro_1601461 = "Um protetor de braço projetado e desenvolvido pela Lin Guild exclusivamente para Yao. Após um tratamento especial, a seda finamente tecida é macia e firme, permitindo que ela dê socos sem arriscar ferimentos. Mais importante, combina perfeitamente com seu traje.",
  str_pet_equip_intro_1601451 = "Amemori carrega uma coleção de objetos secretos desde seu primeiro dia praticando ninjutsu. Na verdade, eles incluem não apenas armas e ferramentas de ninjutsu, mas também outros objetos dos quais a maioria das pessoas nunca ouviu falar. Juntos, eles garantem que Amemori possa completar qualquer missão.",
  str_pet_equip_intro_1501471 = "Um conjunto de utensílios de cozinha que Anzu e Momo não vão a lugar nenhum sem. Isso é tudo o que eles precisam para preparar uma refeição rápida, mas deliciosa. Eles também os usam para bater em bandidos que perturbam sua cozinha.",
  str_pet_equip_intro_1201631 = "Esta placa indica o início do trabalho, emitindo um aplauso nítido que o Tourdog considera a música mais bonita do mundo. O Tourdog está a um passo de realizar o seu sonho sempre que vir ouvir o seu som...",
  str_pet_equip_intro_1601481 = "Diz-se que o rifle foi descoberto em uma ruína misteriosa e entrou na posse de Azure quando ela era pequena. Ele ganha um belo tom azul profundo sob luz solar direta e dispara um tipo especial de bala.",
  str_pet_equip_intro_1501491 = "Uma pequena bolsa que Roy carrega consigo o tempo todo. Contém várias ferramentas, explosivos, peças para os Sweeties (suas abelhas mecânicas) e doces.",
  str_pet_equip_intro_1601501 = "Supostamente é apenas um pequeno e resistente bastão de madeira, mas nas mãos de Lenore, combinado com uma gota de seu sangue e seus Luminatics especiais, ele se transforma em uma foice gigante que derruba todos os inimigos.",
  str_pet_equip_intro_1601511 = "Quando Giles encontrou seu Black Ram—Isaac, ele estava segurando este cajado de madeira em sua mão e, mais tarde, tornou-se uma ferramenta para ele se comunicar com Isaac, permitindo que ele o invocasse e comandasse.",
  str_pet_equip_intro_1501521 = "Parece uma mochila desgastada coberta de remendos, na forma de um gato bizarro de seis olhos. No entanto, May gosta muito dele e nunca o deixa fora de vista.",
  str_pet_equip_intro_1601531 = "A lâmina desta lança é de cor vermelha como se estivesse queimando. Ficou parado Reinhardtenquanto ela enfrentou inúmeras crises e sobreviveu a inúmeras batalhas de vida ou morte. Reinhardt agora dominou totalmente a lança.",
  str_pet_equip_intro_1601541 = "Uma besta encontrada entre relíquias antigas é capaz de disparar flechas rapidamente. Com seus Luminatics e técnicas recém-aprendidas, Vice é capaz de atingir os pontos vitais de seus inimigos com a besta fatalmente.",
  str_pet_equip_intro_1601551 = "Uma vez duas espadas separadas, elas podem ser combinadas em uma espada de ponta dupla quando necessário. Barton a empunha como se fosse um vento veloz varrendo todos esses inimigos.",
  str_pet_equip_intro_1601561 = "Pode parecer o nome de um local, mas é a sombrinha preta que Nina carrega consigo. Ao usar Luminatics, Nina pode convocar todos os tipos de armas.",
  str_pet_equip_intro_1501571 = "A fita que Sanae carrega consigo o tempo todo. Ele não só pode canalizar o Lumina de Sanae para atacar o inimigo, mas também permite que ela manipule seu fantoche para lutar.",
  str_pet_equip_intro_1601581 = [[
A arma do Coringa.
Parece um punhal.]],
  str_pet_equip_intro_1501621 = "A arma de Mona.\nParece o tipo de espada popular entre os ladrões.",
  str_pet_equip_intro_1501601 = [[
A arma de Fox.
Parece uma catana.]],
  str_pet_equip_intro_1601591 = [[
A arma da rainha.
Parece uma luva de boxe.]],
  str_pet_equip_intro_1501611 = [[
A arma de Violet.
Parece uma espada afiada.]],
  str_pet_equip_intro_1501681 = "Depois que Rainbow se estabeleceu no Emerald, o engenheiro do navio construiu uma pistola de água de alta pressão para ela. Embora pareça muito comum, a pressão da água pode ser ajustada para pulverizar água com intensidade variável. No entanto, pode explodir com enorme poder quando usado com a Rainbow's Luminatics.",
  str_pet_equip_intro_1601661 = "Uma pistola de sinalização modificada que é pequena, flexível e fácil de usar. Ele pode lançar pequenas granadas nos inimigos para atacá-los e lançar marcadores para guiar animais treinados para atacar.",
  str_pet_equip_intro_1601671 = "Um baralho de cartas feito especialmente que contém os mistérios da \"Origem\". Victoria deu este baralho de cartas para Jeno quando ele se juntou à Verdadeira Ordem. O soberbo controle de Jeno sobre as cartas permite que ele as use para ativar todos os tipos de poderes mágicos.",
  str_pet_equip_intro_1501651 = "Ao operá-lo pela primeira vez, Ciel dominou o uso desta chave sem um professor. Depois disso, Ciel usou essa chave para completar a montagem de dois conjuntos de mecha dinâmico e até mesmo consertar muitas peças-chave em emergências... Para Ciel, essa chave não é uma ferramenta comum, mas uma extensão de sua habilidade.",
  str_pet_equip_intro_1601641 = "Carleen ganhou novos insights sobre o combate após essa jornada, e essa lança também foi dotada de diferentes habilidades. Até a marca exclusiva mudou! Sem dúvida, isso significa que Carleen tem um domínio inigualável desta lança.",
  str_pet_equip_intro_1501301 = "Não há palavras neste códice de leis especiais. Na verdade, não é para ler, mas para \"lutar\". Somente seu dono sabe como usá-lo.",
  str_pet_equip_intro_1501711 = "Este rifle está equipado com uma lâmina grande e forte. Não afeta a precisão do tiro e é útil em combate corpo a corpo.",
  str_pet_equip_intro_1601701 = "Diz-se que é uma das pistolas favoritas de Pollux. É forte, durável e poderoso. Ela pode aprimorar as balas com suas Luminatics, fazendo com que elas atinjam alvos com maior impacto.",
  str_pet_equip_intro_1401691 = "Depois de uma certa missão e a mando de um amigo, Sadie pegou uma arma que combinava perfeitamente com seu estilo de luta: um taco de beisebol modificado. Após treinamento constante e rigoroso, Sadie pode finalmente canalizar sua força titânica através de seu fiel morcego e enviar qualquer inimigo pelos ares; ela pode até mandar um carro para o alto!",
  str_pet_equip_intro_1601721 = "A primeira câmera de vídeo de Lilica e um presente amoroso de seus pais. Apesar de ser uma câmera de segunda mão, ela a valoriza acima de qualquer outro bem; depois de dominar suas várias funções, Lilica pode até aprimorá-lo com seus Luminatics para atirar em qualquer lugar e a qualquer hora, até mesmo no campo de batalha. Isso fornece a seus aliados o suporte necessário em combate.",
  str_pet_equip_intro_1601731 = "Na realidade, é apenas uma pistola de pederneira comum. No entanto, sob a manutenção meticulosa de Minos, ele pode infundir seus Luminatics para fazê-lo liberar várias vezes seu poder original.",
  str_pet_equip_intro_1501761 = "O nome coletivo de \"Borealis\" e \"Australis\". \"Borealis\" é uma lança de lâmina dupla, enquanto \"Australis\" é uma lança longa. A incrível força de Beretta permite que ela balance facilmente essas duas armas longas que os soldados comuns precisam das duas mãos para usar com uma mão. Ela também pode lançar \"Australis\" para ataques à distância.",
  str_pet_equip_intro_1601751 = "Embora todos esses robôs sejam parecidos, Axelia nunca os misturaria. Feito especialmente pela Federação Illumina para uso de Axelia, isso pode acomodar muitas armas e pode ajudá-la na batalha.",
  str_pet_equip_intro_1601771 = "Este é o microfone usado por Goldie durante as apresentações. Feito de metais preciosos, sincroniza com suas habilidades únicas de transmitir o som de seu canto aos ouvidos de todos os ouvintes, para que suas canções dissipem a densa névoa de todos os corações.",
  str_pet_equip_intro_1601781 = "Embora pareça um bastão de trekking simples, é sólido o suficiente para ser usado como uma arma. Quanto ao caso... contém animais estranhos que atacam os inimigos quando soltos.",
  str_pet_equip_intro_1501801 = "Pode ser simplesmente uma câmera para um repórter iniciante, mas Brandy pode usá-la com muita proficiência para tirar todos os tipos de instantâneos e encontrar as fraquezas de seus inimigos para que ela possa alvejá-los.",
  str_pet_equip_intro_1501831 = "Liqing tem usado esta balança para pesar ervas desde que aprendeu as artes de cura. Sua medição precisa o ajuda a embalar sempre a porção correta e perfeita. O conhecimento de medicina de Liqing melhora à medida que ele se torna mais proficiente no uso da balança.",
  str_pet_equip_intro_1601821 = "Esta adaga é supostamente feita a partir do osso de um dos ancestrais de Yuebai. Possui um tremendo poder de corte e esfaqueamento. Ela tem um vínculo místico com ele, manejando-o com precisão desde o primeiro momento em que colocou as mãos nele. Posteriormente, tornou-se sua arma de assinatura.",
  str_pet_equip_intro_1601811 = "Zhong Xu obteve este anel depois de herdar as Artes da Força Flamejante de sua família como um símbolo do reconhecimento do clã. Sempre que noções de desistir ou se aposentar surgem nele, rachaduras aparecem no objeto. Como o anel torna suas emoções particulares evidentes para os outros, ele raramente o mostra a alguém.",
  str_pet_equip_intro_1601841 = "Lembranças dadas a Jeriah por Hawk e Sacred Python, consideradas a primeira pena e escama que cada um respeitosamente cresceu, uma indicação de sua confiança absoluta em Jeriah. Isso melhora a química deles com ela na batalha.",
  str_pet_equip_intro_1501851 = "Quando Kya se tornou uma mensageira, ela já carregava essa arma ao seu lado, e ela tem servido bem desde então, acompanhando-a para entregar correspondências com segurança em todo o mundo. Ela continua carregando esta besta, acreditando que enquanto a tiver, mesmo que o perigo a encontre durante seu trabalho, ela ainda fará suas entregas no prazo.",
  str_pet_equip_intro_1601861 = "Nascido em família nobre, Tina tem sido extremamente talentosa com espadas desde criança. Esta longa espada a segue há muito tempo. Somente com esta espada ela pode usar a energia Lumina única que ela dominou até seus limites.",
  str_pet_equip_intro_1601891 = "Embora não seja nada como as armas tradicionalmente usadas pelos cavaleiros em Lumopolis, Leyn, que se preocupa mais com o uso prático de uma arma do que com sua aparência, não se importa nem um pouco, o que reflete mais ou menos seu caráter... Leyn pode infundir Luminatics nesta arma para fazê-la girar continuamente, acelerar e ativar um interruptor para fazer Lumina jorrar para destruir seus inimigos.",
  str_pet_equip_intro_1501901 = "Geralmente um cajado, torna-se um longo chicote quando Matthieu infunde-o com Lumina. Chamas nadam descontroladamente por toda parte, liberando uma luz brilhante que adverte os infratores a não se aproximarem. Aqueles que são ousados o suficiente para tentar experimentarão a dor do remorso.",
  str_pet_equip_intro_1501931 = "Kristen tem sido capaz de usar esta lança desde que recebeu treinamento em artes marciais e pode usar Lumina para aumentar seu poder. Ela também pode usá-lo para controlar a água, convocando poderosas torrentes capazes de separar ondas furiosas.",
  str_pet_equip_intro_1601911 = "O selo de cabeça de cavalo no medalhão faz com que pareça extremamente precioso. Dizem que é feito de ouro puro! O mecanismo requintado dentro dele requer Hati e outra pessoa para abri-lo juntos.",
  str_pet_equip_intro_1601921 = "Embora a espada de Leo possa não parecer nada especial em comparação com aquelas armas lendárias, em suas mãos ela se tornou um poderoso símbolo de domínio sobre seu povo. Isso provavelmente se deve, pelo menos em parte, ao carisma inerente de Leo.",
  str_pet_equip_intro_1601991 = "Este rifle de precisão se destaca de qualquer arma de fogo comum devido ao seu material e estrutura exclusivos, cuidadosamente elaborados por um departamento especializado especificamente para Yingel. Mesmo aqueles não familiarizados com armas de fogo podem detectar traços óbvios de modificações feitas nesta arma excepcional.",
  str_pet_equip_intro_1502001 = "Um velho caderno onde Anatoli registra todas as informações que ele reuniu ao longo do tempo. Embora esteja coberto por vários rótulos e tags, você pode vislumbrar ocasionalmente alguns dos rabiscos de Anatoli.",
  str_pet_equip_intro_1602011 = "O pessoal Mia exercia durante seu tempo com os Cavaleiros Lumo. Inicialmente, Mia deu pouca atenção a isso. No entanto, ao vestir seu antigo traje e recuperar esta relíquia do passado, ela percebeu seu notável poder de manifestar perfeitamente sua força, aproveitando suas habilidades passadas e presentes sem esforço.",
  str_pet_equip_intro_1602021 = "Schwartz possui notável habilidade em empunhar uma espada colossal, conhecida por seu peso formidável e natureza desafiadora para os outros manusearem. Por meio de seu treinamento dedicado e domínio de Luminatics, ele empunha sem esforço esta poderosa arma. Além disso, ele aproveita o poder dos Luminatics para criar lâminas semelhantes, concedendo-lhe a capacidade de lançar ataques devastadores contra seus inimigos, ganhar vantagem na batalha e, finalmente, emergir triunfante em seus empreendimentos.",
  str_pet_equip_intro_1502031 = "Um livro grosso e pesado, deixado para trás por sua mãe, Boaz, que era conhecida como a adivinha mais habilidosa de Northland. Este livro inestimável contém extensa pesquisa de Boaz e uma coleção de suas diversas experiências. Em essência, serve como um recurso valioso para aprimorar as habilidades de adivinhação de Jakine, oferecendo assistência significativa em sua prática.",
  str_pet_equip_intro_1502051 = "Ela empunha uma foice grande e pesada tão facilmente quanto faria com uma colher de mexer. Com esta arma mortal em mãos, suas batalhas se tornam tão calmas quanto um chá da tarde. Com um sorriso, ela despacha facilmente seus inimigos sob uma rajada carmesim de ataques implacáveis.",
  str_pet_equip_intro_1602041 = "Apesar de suas decorações ornamentadas, este florete não é apenas para exibição. Quando alimentado pelos Luminatics de Joshua, especialmente sua convicção de proteger sua família, surge com um poder inconcebível.",
  str_pet_equip_intro_1602061 = "Por trás de todo prodígio nos negócios, há um fluxo constante de ideias! Quando os empreendimentos empresariais de Lorelei enfrentam desafios, ela descarrega sua munição, puxa o gatilho desta pistola e ouve o estalo do percussor. Na maioria das vezes, surgem novas faíscas de ideias, tornando-se a arma preferida de Lorelei.",
  str_pet_equip_intro_1602071 = "Uma marca registrada de um verdadeiro cavalheiro é a habilidade de manter a elegância e se vestir adequadamente para qualquer ocasião. Na batalha, ele se adorna com o chapéu e esta arma, que, na realidade, são apenas peças decorativas e não armas funcionais - ele simplesmente acredita que isso evocará uma \"ambientação de batalha\".",
  str_pet_equip_intro_1502081 = "Dizem que essa corrente de aço resistente já foi usada para prender o temível Lagarto Gigante antes de Bopper se tornar um membro do Rediesel Wrench. Embora possa ser apenas uma história exagerada, a corrente de aço é inegavelmente durável! Ela pode suportar facilmente os poderosos golpes e ataques de Bopper.",
  str_pet_equip_intro_1602091 = "Forjada pela reconstituição da Matriz da Máquina Flutuante original, esta lança ressoa com a própria essência de Wrath. Sua afinidade inata com Wrath a torna uma extensão de seu braço e vontade. Uma vez alimentada por seus Luminatics, ela pode derrotar todos os inimigos em combate corpo a corpo e também ser lançada como um dardo para atravessar formações inimigas.",
  str_pet_equip_intro_1502101 = "Assim como o destino de seu portador, esta espada começou como uma arma comum usada no treinamento diário de Joselyne. No entanto, depois que Joselyne a empunhou para defender a Cidade do Crepúsculo, a espada aparentemente adquiriu um poder sobrenatural. Sempre que segurada por Joselyne, a lâmina nunca perde o fio, nunca quebra, mantendo para sempre sua nitidez incomparável.",
  str_pet_equip_intro_1602121 = "O bastão multifuncional de montanhismo, feito de materiais coletados pessoalmente por Antony, é uma ferramenta indispensável para suas expedições. Durante o processo de fabricação, a durabilidade é a única preocupação, resultando em uma aparência pouco impressionante. Após inúmeras modificações, agora está em sua sétima versão, com funções como transmissor, luzes e radar básico.",
  str_pet_equip_intro_1602111 = "Uma vez que Zarya se libertou da névoa do passado, ela percebeu que não era mais aquela gaiola congelada que a aprisionava, mas sim o poder que florescia livremente em suas mãos. Os cristais de gelo que ela condensou, cintilando com uma fluorescência semelhante ao brilho de seu cabelo, são apenas flocos de neve recriados, formados por um coração mais determinado.",
  str_pet_equip_intro_1502131 = "Esses braços robóticos multiarticulados são um tipo alternativo de apêndice instalado no corpo de No. 33, sendo mais flexíveis, convenientes e mortais do que os braços médios de um Auroriano. Eles podem segurar várias ferramentas de reparo ao mesmo tempo para penetrar estruturas mecânicas e realizar manutenção, e também podem ser equipados com garras e carga elétrica para penetrar nas defesas inimigas.",
  str_pet_equip_intro_1501871 = "Li Tianxian carrega um longo estandarte que dizem ajudá-lo na adivinhação. No entanto, sua função principal é atrair todos os tipos de clientes em potencial. Porém, não se deve subestimar este estandarte - em batalha, Li Tianxian pode usá-lo para liberar seus Luminatics únicos, em conjunto com seu cúmplice aviário, para atacar seus inimigos de locais inesperados.",
  str_pet_equip_intro_1601881 = "Este pipa possui uma ampla gama tonal capaz de expressar diversas emoções. Dantang também descobriu que quanto mais ela toca, maior é seu controle sobre o Lumina, então ela faz questão de levá-lo aonde quer que vá.",
  str_pet_equip_intro_1602141 = "Uma habilidade única com a qual Rebecca nasceu, ela a protege de ameaças potenciais e concede a ela o poder de proteger seus entes queridos também. A única coisa é que, no que diz respeito a Rebecca, não está totalmente claro se esse poder é uma bênção ou uma maldição...",
  str_pet_equip_intro_1502151 = "Isa pagou um bom dinheiro pelo seu precioso chicote - uma arma que tem um excelente desempenho no campo de batalha e inflige uma dor insuportável em suas vítimas. Ela é extremamente apegada a esta arma e explorou ao máximo sua vasta gama de possíveis usos, incluindo seus favoritos pessoais - açoitar e amarrar. Claro, esta arma também tem um uso que supera todos os outros em termos de importância - proteger Rebecca.",
  str_pet_equip_intro_1602161 = "O guarda-chuva mecânico favorito de Xuan Ji, que incorpora as habilidades das escolas de artesanato do Reino Ye, é ágil e versátil como um animal e tão portátil e fácil de desmontar quanto um objeto inanimado. Ele pode armazenar libélulas de cobre e pássaros mecânicos, além de disparar flechas e uma saraivada de peles. Quando empunhado, pode ser usado para esfaquear, golpear, deslizar e cortar, usado como escudo ou arado... e para se esconder da chuva.",
  str_pet_equip_intro_1602181 = "Sheol recebeu esta valiosa lembrança dourada de sua mãe. O mais importante é que é extremamente compatível com o Lumina de Sheol, permitindo que ela libere poderes incríveis.",
  str_pet_equip_intro_1602191 = "Como se estivesse rasgando a fita vermelha da vida, o cajado dourado transformou-se em uma pesada armadura de garra que mascarava bem a escuridão e a violência sob sua elegância. O ataque da garra flamejante é como um carro de guerra em carga. E este é o verdadeiro Senhor Sombrio.",
  str_pet_equip_intro_1502201 = "A mochila de Virgílio está cheia de todos os tipos de comida deliciosa e um conjunto de ferramentas de avaliação. No entanto, Virgílio os combinou de uma maneira muito estranha para que ele possa usá-los a qualquer momento. Provavelmente, Virgílio é a única pessoa que pode usá-los neste mundo.",
  str_pet_equip_intro_1602211 = "Bool é um nanorobô que vive em Algol e dizem que causou ao seu mestre fraturas e tendões rompidos. No entanto, Bool se torna realmente feroz contra qualquer coisa que ameace a existência de seu mestre.",
  str_pet_equip_intro_1602231 = "A primeira escama derramada por Chen'ni, preservada por sua importância. Como um testemunho silencioso das histórias de Longzhou e Chen'ni, ela atravessa milênios com ela. Sempre que Chen'ni a usa para manifestar sua verdadeira forma, a escama carrega marcas invisíveis de suas memórias.",
  str_pet_equip_intro_1502241 = "O companheiro de Luo Song, Ding, é um fiendling tigre ainda aprimorando suas habilidades. Seu treinamento atual se concentra no aprimoramento físico e crescimento. Quanto a se envolver em um pensamento suave e fala articulada como os aurorianos, bem, esse é um objetivo para o futuro.",
  str_pet_equip_intro_1602251 = "Era uma vez uma lança comum feita de madeira de freixo, mas depois que Bethlehem a modificou e a infundiu com Lúmina, ela agora pode liberar um poder tremendo nas mãos de Tiare. Os nortistas acreditam que esta lança possui o poder de invocar trovões e chamar ventos, por isso a apelidaram de \"Chamadora do Vento\". Na realidade, Tiare nunca lhe deu um nome.",
  str_pet_equip_intro_1202261 = "O coaxar irresistivelmente cativante e provou ser bastante útil no Sonho. Embora seja difícil para o príncipe realizar milagres na vida real, seu calor e bondade sempre nos inspirarão!",
  str_pet_equip_intro_1602271 = "Se você ver um drone passar pelo céu num piscar de olhos, Rachel provavelmente não está longe. Os três Caçadores de Águia que a acompanham em todas as missões são modificados por suas próprias mãos. Cada um é capaz de executar tarefas de reconhecimento o tempo todo, incluindo reconhecimento, interferência, rastreamento e mais. Sua velocidade e desempenho são incomparáveis no exército da Federação Illumina.",
  str_pet_equip_intro_1502281 = "\"Conan, o Iluminado\" foi o primeiro mangá que Zeta já leu, bem como o catalisador que desencadeou sua obsessão por role-playing. Como resultado, Zeta tende a nomear seu robô mais forte de \"Conan\" como uma homenagem à sua série mais amada.",
  str_pet_equip_intro_1602291 = "Este pequeno console requintado parece ser o mesmo modelo que a primeira máquina de jogos da Batia. Até hoje, ela ainda considera aquele console de primeira geração desgastado pelo tempo como sua primeira amiga e mentora.",
  str_pet_equip_intro_1602301 = "Quando ela ganhou poder do passagem misteriosa, a Bíblia Sangrenta de Victoria se desdobrou subitamente e assumiu uma nova forma. Profecias jorram como rápidos, esgotando toda a sabedoria para levar o precursor da mudança a um novo caminho.",
  str_pet_equip_intro_1602311 = "A empunhadura aparentemente vazia, quando segurada por Wilhelm, goteja sangue que forma a lâmina. O conceito da espada é \"Domínio\", seu verdadeiro nome \"Maré Carmesim\". A luz vermelha feroz perfura nuvens e céu, espalhando tudo em seu caminho como pétalas caindo.",
  str_pet_equip_intro_1502321 = "Talvez santificado pelo Sangue Raro pelo Senhor da Verdade, os Nails Piedosos se tornaram uma espada de sangue em forma de cruz - a Espada do Sangue Sagrado. É tanto a punição quanto a salvação de Nails. Em nome dos santos, Nails se fere com ela, liberando Sangue Sagrado para purificar o mundo.",
  str_pet_equip_intro_1602331 = "Um cajado que emite um forte brilho. Mesmo quando inativo, continua a cintilar com uma brilhante deslumbrante. Banhados nesta luz, não apenas o portador, mas também aqueles ao redor sentirão seus corações se tornando mais brilhantes.",
  str_pet_equip_intro_1602341 = "As flechas que dispara brilham como estrelas na escuridão, daí o seu nome. Ninguém gostaria de ser alvo de tal arco na escuridão.",
  str_pet_equip_intro_1502351 = "Dizem que esta espada tem vontade própria e escolhe seu portador. Mesmo o mais habilidoso não consegue controlá-la sem uma alma nobre.",
  str_pet_equip_intro_1602371 = "Uma concha imaculada que reflete luzes. Apenas o Clã Miragem sabe como tocar. Diz-se que é uma junção do Osso Miragem. Quando Maya a pegou, ela claramente viu a essência do mundo, e seu coração começou a bater em harmonia com seus ancestrais.\nO mundo May pode ser uma fantasia, mas as luzes gloriosas entre esses momentos fugazes são dignas de uma bela elegia.",
  str_pet_equip_intro_1602381 = "Um emblema que Aquiles presenteou a Anthony. Está cheio de imenso poder. Ele sinceramente desejou que ajudasse o clã Longinus a lutar contra o destino. No entanto, cada geração do clã Longinus não conseguia suportar usar o emblema, deixando-o permanecer apenas como um símbolo de seu nobre juramento. Até Mithra só o usaria para aprimorar sua lâmina.",
  str_pet_equip_name_1602411 = "Chamas em Chamas",
  str_pet_equip_intro_1602411 = "A Lumina inata; o coração cinético artificial dado pelo Comitê; o emblema de armazenamento de energia concedido por Victoria; o poder de reverter a vida presenteado pelo fantasma, Ursura... e o coração inabalável de Pepita que ainda bate forte mesmo fora de seu peito.\nJuntos, eles criam este milagre enquanto Pepita acende o poder de seu próprio coração.",
  str_pet_equip_name_1702361 = "Luar de Ludweiss",
  str_pet_equip_intro_1702361 = "Uma lâmina colossal, forjada especificamente para Claymore. A lâmina está marcada por inúmeras batalhas, mas esta arma de aparência brutal nunca voltou sua lâmina para um Auroriano. Foi por essa razão que Aquiles a nomeou em homenagem ao seu amigo gentil - \nUm testemunho do verdadeiro propósito da lâmina: proteção.",
  str_pet_equip_string = "Equipamento",
  str_pet_equip_up_lv = "Melhorar",
  str_pet_equip_skill = "Habilidades de Equip.",
  str_pet_equip_att = "Aptidão de Equipamento",
